<?php require_once '../config.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=(int)($_POST['quantity']??0);if($qty<1||$qty>500)$msg='Choose a quantity from 1 to 500.';else{$ins=db()->prepare('INSERT INTO product_codes(code,status) VALUES(?,"active")');$made=[];for($i=0;$i<$qty;$i++){do{$code=strtoupper(bin2hex(random_bytes(6)));$q=db()->prepare('SELECT id FROM product_codes WHERE code=?');$q->execute([$code]);}while($q->fetch());$ins->execute([$code]);$made[]=$code;}$_SESSION['new_codes']=$made;flash($qty.' unique codes generated. Save or print this list securely.');redirect('codes.php?generated=1');}}
$codes=db()->query('SELECT p.code,p.status,p.created_at,p.redeemed_at,c.name FROM product_codes p LEFT JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC LIMIT 100')->fetchAll();page_start('Product code management');if(isset($_GET['generated'])&&!empty($_SESSION['new_codes'])){$list=$_SESSION['new_codes'];unset($_SESSION['new_codes']);?><section class="panel"><h2>New codes – save this list</h2><p>Print these codes and place one unique code inside each eligible product box. Do not publish this list.</p><textarea readonly rows="8" class="code-list"><?=e(implode("\n",$list))?></textarea><button class="btn" onclick="navigator.clipboard.writeText(document.querySelector('.code-list').value)">Copy codes</button></section><?php }?><section class="panel"><h2>Generate a batch</h2><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Number of codes (1–500)<input type="number" name="quantity" min="1" max="500" value="20" required></label><button class="btn">Generate unique codes</button></form></section><section class="panel"><h2>Latest 100 codes</h2><div class="table-wrap"><table><tr><th>Code</th><th>Status</th><th>Customer</th><th>Created</th><th>Redeemed</th></tr><?php foreach($codes as $c):?><tr><td><?=e($c['code'])?></td><td><span class="pill <?=e($c['status'])?>"><?=e($c['status'])?></span></td><td><?=e($c['name']??'—')?></td><td><?=e($c['created_at'])?></td><td><?=e($c['redeemed_at']??'—')?></td></tr><?php endforeach;?></table></div></section><?php page_end();?>
